package com.ocker.core;

import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.databind.node.*;
import org.apache.poi.xwpf.extractor.XWPFWordExtractor; import org.apache.poi.xwpf.usermodel.XWPFDocument;
import javax.swing.text.BadLocationException; import javax.swing.text.rtf.RTFEditorKit;
import java.io.*; import java.nio.charset.StandardCharsets; import java.nio.file.*; import java.security.*; import java.time.*; import java.util.*; import java.util.stream.*;
import static com.ocker.core.OckerTypes.*;

/** Public OCKER operations: validation, portable JSON, Docling PDF import and assisted chronology work. */
public final class Ocker {
 private Ocker(){} public static final ObjectMapper JSON=new ObjectMapper().findAndRegisterModules();
 public static OckerRecord createRecord(String title){String now=Instant.now().toString();return new OckerRecord("ocker","0.1.0",id(),title,now,now,List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),null);}
 public static OckerGraph graph(OckerRecord record){return OckerGraph.from(record);}
 public static OckerRecordBuilder recordBuilder(String title){return OckerRecordBuilder.create(title);}
 public static OckerRecordBuilder recordBuilder(OckerRecord record){return OckerRecordBuilder.from(record);}
 public static OckerRecord parseRecord(String json) throws IOException { JsonNode raw=JSON.readTree(json); SchemaValidation.record(raw); OckerRecord r=JSON.treeToValue(raw,OckerRecord.class); validateStrict(r); return r; }
 public static OckerRecord importRecord(String json) throws IOException { return parseRecord(json); }
 public static String exportRecord(OckerRecord r) throws IOException { validateStrict(r); return JSON.writerWithDefaultPrettyPrinter().writeValueAsString(r); }
 public static Intermediate parseIntermediate(String json) throws IOException { JsonNode raw=JSON.readTree(json); SchemaValidation.document(raw); Intermediate i=JSON.treeToValue(raw,Intermediate.class); if(i==null||!"ocker-document".equals(i.format())||!"0.1.0".equals(i.version())||i.document()==null)throw new ValidationException(List.of("Expected ocker-document version 0.1.0")); validateIntermediate(i); return i; }
 public static String exportIntermediate(Intermediate i) throws IOException { if(i==null||i.document()==null)throw new ValidationException(List.of("intermediate document required")); validateIntermediate(i); return JSON.writerWithDefaultPrettyPrinter().writeValueAsString(i); }
 public static void validateIntermediate(Intermediate i){
  if(i==null)throw new ValidationException(List.of("Intermediate required"));SchemaValidation.document(JSON.valueToTree(i));
  var r=createRecord("Intermediate validation");
  validateStrict(new OckerRecord(r.format(),r.version(),r.id(),r.title(),r.createdAt(),r.updatedAt(),List.of(),List.of(i.document()),List.of(),List.of(),List.of(),List.of(),i.asset()==null?List.of():List.of(i.asset()),null));
 }
 public static void validate(OckerRecord r) { List<String> e=new ArrayList<>(); if(r==null||!"ocker".equals(r.format())||!"0.1.0".equals(r.version()))e.add("Expected format ocker version 0.1.0"); if(r==null){throw new ValidationException(e);} Set<String> ids=new HashSet<>(); add(ids,e,r.id(),"record"); r.actors().forEach(x->add(ids,e,x.id(),"actor")); r.documents().forEach(d->{add(ids,e,d.id(),"document");Set<String> p=new HashSet<>();d.paragraphs().forEach(q->{if(!p.add(q.id()))e.add("duplicate paragraph "+q.id());if(q.page()<1)e.add("paragraph page must be positive");});}); r.events().forEach(x->{add(ids,e,x.id(),"event");if(x.date()==null||!Set.of("day","month","year","range","unknown").contains(x.date().precision()))e.add("bad date precision for "+x.id()); refs(r,x.sources(),e);}); Set<String> eventIds=r.events().stream().map(Event::id).collect(Collectors.toSet()); r.relationships().forEach(x->{add(ids,e,x.id(),"relationship");if(!eventIds.contains(x.from())||!eventIds.contains(x.to()))e.add("relationship event missing "+x.id());if(!Set.of("supports","contradicts").contains(x.type()))e.add("bad relationship type "+x.id());refs(r,x.sources(),e);}); r.notes().forEach(x->{add(ids,e,x.id(),"note");if(!eventIds.contains(x.eventId()))e.add("note event missing "+x.id());});r.authorities().forEach(x->{add(ids,e,x.id(),"authority");if(!eventIds.contains(x.eventId()))e.add("authority event missing "+x.id());if(!Set.of("blue","lavender","mint","peach","slate").contains(x.color()))e.add("bad authority color");});r.assets().forEach(x->{add(ids,e,x.id(),"asset");asset(x,e);}); if(!e.isEmpty())throw new ValidationException(e); }
 public static void validateStrict(OckerRecord r) { validate(r); SchemaValidation.record(JSON.valueToTree(r)); List<String> errors=new ArrayList<>(); Set<String> actors=r.actors().stream().map(Actor::id).collect(Collectors.toSet()), assets=r.assets().stream().map(Asset::id).collect(Collectors.toSet()); for(Document d:r.documents())if(d.assetId()!=null&&!assets.contains(d.assetId()))errors.add("document asset missing "+d.assetId()); for(Event e:r.events()){for(String actor:e.actorIds())if(!actors.contains(actor))errors.add("event actor missing "+actor);for(Source s:e.sources())exactQuote(r,s,errors);}for(Relationship x:r.relationships())for(Source s:x.sources())exactQuote(r,s,errors);for(Asset a:r.assets())if(a.derivedFrom()!=null&&!assets.contains(a.derivedFrom()))errors.add("derived asset missing "+a.derivedFrom());additionalSemantics(r,errors);if(!errors.isEmpty())throw new ValidationException(errors); }
 private static void additionalSemantics(OckerRecord r,List<String> errors){
 Set<String> actors=r.actors().stream().map(Actor::id).collect(Collectors.toSet()),pairs=new HashSet<>();
 for(Event event:r.events()){
  DateValue d=event.date();try{switch(d.precision()){case "day"->LocalDate.parse(d.value());case "month"->YearMonth.parse(d.value());case "year"->Year.parse(d.value());case "range"->{LocalDate a=LocalDate.parse(d.value()),b=LocalDate.parse(d.end());if(b.isBefore(a))errors.add("date range end precedes start");}default->{}}}catch(Exception ex){errors.add("invalid calendar date "+event.id());}
 }
 for(Relationship rel:r.relationships()){if(rel.from().equals(rel.to()))errors.add("self relationship");if(!pairs.add(relationKey(rel.from(),rel.to(),rel.type())))errors.add("duplicate relationship");if(rel.provenance().authorId()!=null&&!actors.contains(rel.provenance().authorId()))errors.add("relationship author missing");}
 for(Note n:r.notes()){if(n.authorId()!=null&&!actors.contains(n.authorId()))errors.add("note author missing");if(java.time.OffsetDateTime.parse(n.updatedAt()).isBefore(java.time.OffsetDateTime.parse(n.createdAt())))errors.add("note update precedes creation");}
 for(Authority a:r.authorities()){if(a.authorId()!=null&&!actors.contains(a.authorId()))errors.add("authority author missing");if(a.sourceUrl()!=null&&!a.sourceUrl().matches("(?i)^https?://.*"))errors.add("authority URL must use HTTP(S)");}
 Map<String,Asset> assets=r.assets().stream().collect(Collectors.toMap(Asset::id,x->x));
 for(Asset a:r.assets()){Set<String> seen=new HashSet<>();seen.add(a.id());String parent=a.derivedFrom();while(parent!=null&&assets.containsKey(parent)){if(!seen.add(parent)){errors.add("asset derivation cycle");break;}parent=assets.get(parent).derivedFrom();}}
 for(Event event:r.events())for(Source source:event.sources())checkSource(r,source,errors);
 for(Relationship rel:r.relationships())for(Source source:rel.sources())checkSource(r,source,errors);
 }
 private static void checkSource(OckerRecord r,Source source,List<String> errors){
 Document d=r.documents().stream().filter(x->x.id().equals(source.documentId())).findFirst().orElse(null);
 if(source.page()!=null&&d!=null&&d.paragraphs().stream().noneMatch(p->p.page()==source.page()))errors.add("source page missing");
 Selector selector=source.selector();if(selector!=null&&selector.end()!=null&&selector.start()!=null&&selector.end()<selector.start())errors.add("selector end precedes start");
 }
 private static void exactQuote(OckerRecord r,Source s,List<String> errors){Document d=r.documents().stream().filter(x->x.id().equals(s.documentId())).findFirst().orElse(null);if(d!=null&&s.paragraphId()!=null){Paragraph p=d.paragraphs().stream().filter(x->x.id().equals(s.paragraphId())).findFirst().orElse(null);if(p!=null&&s.quote()!=null&&!p.text().contains(s.quote()))errors.add("source quote is not exact excerpt "+s.paragraphId());}}
 private static void refs(OckerRecord r,List<Source>s,List<String>e){Map<String,Document> ds=r.documents().stream().collect(Collectors.toMap(Document::id,x->x));Set<String> as=r.assets().stream().map(Asset::id).collect(Collectors.toSet());for(Source x:s){Document d=ds.get(x.documentId());if(d==null)e.add("source document missing "+x.documentId());else if(x.paragraphId()!=null&&!d.paragraphs().stream().anyMatch(p->p.id().equals(x.paragraphId())))e.add("source paragraph missing "+x.paragraphId());if(x.assetId()!=null&&!as.contains(x.assetId()))e.add("source asset missing "+x.assetId());}}
 private static void asset(Asset a,List<String>e){try{if(a.data()!=null){byte[] b=Base64.getDecoder().decode(a.data());if(b.length!=a.byteLength())e.add("asset length mismatch "+a.id());if(!hex(MessageDigest.getInstance("SHA-256").digest(b)).equals(a.sha256()))e.add("asset hash mismatch "+a.id());}}catch(Exception x){e.add("invalid asset "+a.id());}}
 private static void add(Set<String>s,List<String>e,String x,String kind){if(x==null||x.isBlank())e.add(kind+" id required");else if(!s.add(x))e.add("duplicate id "+x);} private static String id(){return UUID.randomUUID().toString();} private static String hex(byte[]b){return HexFormat.of().formatHex(b);}
 /** Imports a PDF through the configured Docling Serve client. */
 public static Intermediate parsePdf(Path path,String documentId,String title,String kind,OckerOptions o) throws IOException {return (o==null?DoclingServeClient.local():o.doclingServe).parsePdf(path,documentId,title,kind,o);}
 public static Intermediate parseDocument(Path path,String documentId,String title,String kind,OckerOptions o) throws IOException {
  String extension=extension(path);if("pdf".equals(extension)){progress(o,"converting","Converting PDF with Docling Serve");return parsePdf(path,documentId,title,kind,o);}progress(o,"reading","Reading "+extension.toUpperCase(Locale.ROOT));if(o.cancellation.cancelled())throw new java.util.concurrent.CancellationException();byte[] raw=Files.readAllBytes(path);String text=switch(extension){case "txt"->new String(raw,StandardCharsets.UTF_8);case "rtf"->rtfText(raw);case "docx"->docxText(raw);default->throw new IllegalArgumentException("Unsupported document type: ."+extension);};List<Paragraph> ps=paragraphs(documentId,text);if(ps.isEmpty())throw new IllegalArgumentException("Document has no extractable text.");Asset a=new Asset(id(),path.getFileName().toString(),mimeType(extension),hex(sha(raw)),raw.length,Base64.getEncoder().encodeToString(raw),null,null,null,null);return new Intermediate("ocker-document","0.1.0",new Document(documentId,title==null?path.getFileName().toString():title,kind==null?"report":kind,null,a.id(),ps),a);
 }
 private static String extension(Path path){String name=path.getFileName().toString();int dot=name.lastIndexOf('.');return dot<0?"":name.substring(dot+1).toLowerCase(Locale.ROOT);}
 private static String rtfText(byte[] raw) throws IOException {try{RTFEditorKit kit=new RTFEditorKit();javax.swing.text.Document document=kit.createDefaultDocument();kit.read(new ByteArrayInputStream(raw),document,0);return document.getText(0,document.getLength());}catch(BadLocationException error){throw new IOException("Could not read RTF",error);}}
 private static String docxText(byte[] raw) throws IOException {try(XWPFDocument document=new XWPFDocument(new ByteArrayInputStream(raw));XWPFWordExtractor extractor=new XWPFWordExtractor(document)){return extractor.getText();}}
 private static List<Paragraph> paragraphs(String documentId,String text){List<Paragraph> paragraphs=new ArrayList<>();String[] pages=text.split("\\f",-1);for(int index=0;index<pages.length;index++){int page=index+1,number=0;for(String part:pages[index].split("(?m)\\n\\s*\\n|\\r?\\n")){part=part.trim();if(!part.isBlank())paragraphs.add(new Paragraph(documentId+"-p"+page+"-"+(++number),page,"p"+page+"."+number,part));}}return paragraphs;}
 private static String mimeType(String extension){return switch(extension){case "pdf"->"application/pdf";case "txt"->"text/plain";case "rtf"->"application/rtf";case "docx"->"application/vnd.openxmlformats-officedocument.wordprocessingml.document";default->"application/octet-stream";};}
 private static byte[] sha(byte[]x){try{return MessageDigest.getInstance("SHA-256").digest(x);}catch(Exception e){throw new IllegalStateException(e);}}
 public static OckerRecord buildChronology(OckerRecord base,Intermediate in,OckerOptions o) throws Exception {validateIntermediate(in);progress(o,"extracting","Extracting chronology"); if(o.cancellation.cancelled())throw new java.util.concurrent.CancellationException(); if(o.llm==null)throw new IllegalStateException("An LLM adapter is required for extraction");ObjectNode input=JSON.valueToTree(in.document());JsonNode res=o.llm.complete("extract",prompt(o.promptLocale,"extract"),input,o.cancellation);if(!res.isObject()||!res.path("events").isArray())throw new ValidationException(List.of("Extraction adapter must return an events array"));List<Event> events=new ArrayList<>(base.events());for(JsonNode x:res.path("events")){if(o.cancellation.cancelled())throw new java.util.concurrent.CancellationException();if(!x.path("paragraphIds").isArray()||x.path("paragraphIds").isEmpty())throw new ValidationException(List.of("At least one source paragraph is required"));List<Source> src=new ArrayList<>();for(JsonNode p:x.path("paragraphIds")){Paragraph q=in.document().paragraphs().stream().filter(z->z.id().equals(p.asText())).findFirst().orElseThrow(()->new ValidationException(List.of("Unknown paragraph id "+p.asText())));src.add(new Source(in.document().id(),q.id(),q.page(),q.text(),in.asset()==null?null:in.asset().id(),new Selector("text",null,null,q.page())));}JsonNode d=x.path("date");DateValue date=JSON.convertValue(d,DateValue.class);events.add(new Event(id(),x.path("title").asText(),x.path("summary").asText(),date,x.path("assertedBy").asText(null),List.of(),src,x.path("status").asText(null),x.path("narrative").asText(null),null));} List<Document> ds=new ArrayList<>(base.documents());ds.add(in.document());List<Asset> as=new ArrayList<>(base.assets());if(in.asset()!=null)as.add(in.asset());OckerRecord r=new OckerRecord(base.format(),base.version(),base.id(),base.title(),base.createdAt(),Instant.now().toString(),base.actors(),ds,events,base.relationships(),base.notes(),base.authorities(),as,base.extensions());validateStrict(r);progress(o,"completed","Chronology built");return r; }
 public static OckerRecord findRelationships(OckerRecord r,OckerOptions o) throws Exception {progress(o,"relating","Assessing relationships");if(o.cancellation.cancelled())throw new java.util.concurrent.CancellationException();if(o.llm==null)throw new IllegalStateException("An LLM adapter is required for relationships");JsonNode out=o.llm.complete("relate",prompt(o.promptLocale,"relate"),JSON.valueToTree(r.events()),o.cancellation);if(!out.isObject()||!out.path("relationships").isArray())throw new ValidationException(List.of("Relationship adapter must return a relationships array"));List<Relationship> all=new ArrayList<>(r.relationships());Set<String> seen=all.stream().map(x->relationKey(x.from(),x.to(),x.type())).collect(Collectors.toSet());Set<String> es=r.events().stream().map(Event::id).collect(Collectors.toSet());for(JsonNode x:out.path("relationships")){if(o.cancellation.cancelled())throw new java.util.concurrent.CancellationException();String f=x.path("from").asText(),t=x.path("to").asText(),type=x.path("type").asText();if(!es.contains(f)||!es.contains(t)||!Set.of("supports","contradicts").contains(type)||x.path("rationale").asText().isBlank())throw new ValidationException(List.of("Invalid inferred relationship"));if(seen.add(relationKey(f,t,type)))all.add(new Relationship(id(),f,t,type,x.path("rationale").asText(),new Provenance("llm",Instant.now().toString(),o.authorId),List.of(),null));}OckerRecord n=copy(r,all,r.notes(),r.authorities());progress(o,"completed","Relationships assessed");return n; }
 public static OckerRecord addNote(OckerRecord r,String eventId,String body,double x,double y,String author){requireEvent(r,eventId);String now=Instant.now().toString();List<Note> n=new ArrayList<>(r.notes());n.add(new Note(id(),eventId,body,new Position(x,y),now,now,author,null));return copy(r,r.relationships(),n,r.authorities());}
 public static OckerRecord editNote(OckerRecord r,Note note){requireEvent(r,note.eventId());List<Note> n=r.notes().stream().map(x->x.id().equals(note.id())?new Note(x.id(),note.eventId(),note.body(),note.position(),x.createdAt(),Instant.now().toString(),note.authorId(),note.extensions()):x).toList();return copy(r,r.relationships(),n,r.authorities());}
 public static OckerRecord deleteNote(OckerRecord r,String noteId){return copy(r,r.relationships(),r.notes().stream().filter(n->!n.id().equals(noteId)).toList(),r.authorities());}
 public static OckerRecord addAuthority(OckerRecord r,Authority a){requireEvent(r,a.eventId());List<Authority>x=new ArrayList<>(r.authorities());x.add(a);return copy(r,r.relationships(),r.notes(),x);} public static OckerRecord deleteAuthority(OckerRecord r,String id){return copy(r,r.relationships(),r.notes(),r.authorities().stream().filter(a->!a.id().equals(id)).toList());}
 public static OckerRecord editAuthority(OckerRecord r,Authority authority){requireEvent(r,authority.eventId()); if(r.authorities().stream().noneMatch(a->a.id().equals(authority.id())))throw new ValidationException(List.of("authority missing "+authority.id())); return copy(r,r.relationships(),r.notes(),r.authorities().stream().map(a->a.id().equals(authority.id())?new Authority(a.id(),authority.eventId(),authority.title(),authority.citation(),authority.type(),authority.color(),authority.pinpoint(),authority.court(),authority.jurisdiction(),authority.sourceUrl(),authority.body(),a.createdAt(),Instant.now().toString(),authority.authorId(),authority.extensions()):a).toList());}
 private static void requireEvent(OckerRecord r,String e){if(r.events().stream().noneMatch(x->x.id().equals(e)))throw new ValidationException(List.of("event missing "+e));}
 private static OckerRecord copy(OckerRecord r,List<Relationship> rel,List<Note> notes,List<Authority> auth){OckerRecord n=new OckerRecord(r.format(),r.version(),r.id(),r.title(),r.createdAt(),Instant.now().toString(),r.actors(),r.documents(),r.events(),rel,notes,auth,r.assets(),r.extensions());validateStrict(n);return n;}
 private static void progress(OckerOptions o,String p,String m){o.progress.accept(new OckerOptions.Progress(p,m));}
 private static String relationKey(String a,String b,String type){return (a.compareTo(b)<0?a+"|"+b:b+"|"+a)+"|"+type;}
 /** Returns one complete, locale-matched public instruction; data and JSON keys stay separate and English. */
 public static String prompt(PromptLocale locale,String task){
  if(!Set.of("extract","relate").contains(task))throw new IllegalArgumentException("Unsupported prompt task: "+task);
  PromptLocale selected=locale==null?PromptLocale.EN:locale;
  try(InputStream input=Ocker.class.getResourceAsStream("/prompts.json")){
   if(input==null)throw new IllegalStateException("Missing generated prompt library resource");
   JsonNode root=JSON.readTree(input).path("locales");JsonNode value=root.path(selected.tag()).path(task);
   if(!value.isTextual()||value.asText().isBlank())value=root.path("en").path(task);
   if(!value.isTextual()||value.asText().isBlank())throw new IllegalStateException("Missing prompt template for "+selected.tag()+"/"+task);
   return value.asText();
  }catch(IOException error){throw new IllegalStateException("Could not read the prompt library",error);}
 }
 public static final class ValidationException extends IllegalArgumentException { public ValidationException(List<String> errors){super(String.join("; ",errors));} }
}
